    while (i < n && s[i] == ' ') i++;
    if (i < n && (s[i] == '+' || s[i] == '-')) sign = (s[i++] == '-') ? -1 : 1;
    while (i < n && isdigit(s[i])) {
        if (num > INT_MAX / 10 || (num == INT_MAX / 10 && s[i] - '0' > 7))
            return sign == 1 ? INT_MAX : INT_MIN;
        num = num * 10 + (s[i++] - '0');
    }
    return num * sign;
}

